parameters.jsCode:
const message = $json;

const subject = String(
  message.Subject ||
  message.subject ||
  ''
).trim();

const snippet = String(
  message.snippet ||
  ''
).trim();

const bookingEventId = String(message.id || '');
const gmailThreadId = String(message.threadId || '');

function capture(text, pattern) {
  const match = String(text || '').match(pattern);
  return match ? String(match[1] || '').trim() : '';
}

function titleCase(value) {
  return String(value || '')
    .replace(/[._-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, character => character.toUpperCase());
}

/*
Example subject:
New Event: Sample Prospect - 03:30 Thu, 23 Jul 2026 - 30 Minute Meeting
*/
const subjectMatch = subject.match(
  /^New Event:\s*(.+?)\s*-\s*(\d{1,2}:\d{2}(?:\s*[AP]M)?)\s+[A-Za-z]{3,9},\s*(\d{1,2}\s+[A-Za-z]{3,9}\s+\d{4})\s*-\s*(.+)$/i
);

const subjectProspectName = subjectMatch
  ? subjectMatch[1].trim()
  : '';

const subjectTime = subjectMatch
  ? subjectMatch[2].trim()
  : '';

const subjectDate = subjectMatch
  ? subjectMatch[3].trim()
  : '';

const subjectEventType = subjectMatch
  ? subjectMatch[4].trim()
  : '';

const prospectName =
  capture(
    snippet,
    /Invitee:\s*(.+?)\s+Invitee Email:/i
  ) ||
  subjectProspectName;

const email = capture(
  snippet,
  /Invitee Email:\s*([^\s]+@[^\s]+)\s+Event Date\/Time:/i
).toLowerCase();

const eventType =
  capture(
    snippet,
    /Event Type:\s*(.+?)\s+Invitee:/i
  ) ||
  subjectEventType ||
  'Calendly meeting';

const nameParts = prospectName
  .split(/\s+/)
  .filter(Boolean);

const firstName = nameParts.shift() || '';
const lastName = nameParts.join(' ');

const emailDomain = email.includes('@')
  ? email.split('@')[1]
  : '';

const freeEmailDomains = new Set([
  'gmail.com',
  'googlemail.com',
  'yahoo.com',
  'outlook.com',
  'hotmail.com',
  'icloud.com',
  'proton.me',
  'protonmail.com'
]);

const isFreeEmail =
  Boolean(emailDomain) &&
  freeEmailDomains.has(emailDomain);

const companyDomain = isFreeEmail
  ? ''
  : emailDomain;

const companyName = companyDomain
  ? titleCase(companyDomain.split('.')[0])
  : '';

/* Parse meeting date and time from subject */
let meetingStart = '';
let meetingParseStatus = 'failed';
let meetingParseError = '';

if (!subjectMatch) {
  meetingParseError =
    'Could not extract meeting date and time from the email subject.';
} else {
  const hasMeridiem =
    /\b(?:AM|PM)\b/i.test(subjectTime);

  const format = hasMeridiem
    ? 'd LLL yyyy h:mm a'
    : 'd LLL yyyy HH:mm';

  const dateTimeText =
    `${subjectDate} ${subjectTime}`;

  const parsedDateTime = DateTime.fromFormat(
    dateTimeText,
    format,
    {
      locale: 'en'
    }
  );

  if (parsedDateTime.isValid) {
    meetingStart = parsedDateTime.toISO();
    meetingParseStatus = 'success';
  } else {
    meetingParseError =
      parsedDateTime.invalidExplanation ||
      'Invalid meeting date or time.';
  }
}

/* Validate required extracted fields */
const missingFields = [];

if (!prospectName) {
  missingFields.push('prospect_name');
}

if (!email) {
  missingFields.push('email');
}

if (!bookingEventId) {
  missingFields.push('booking_event_id');
}

if (!meetingStart) {
  missingFields.push('meeting_start');
}

const extractionStatus =
  missingFields.length === 0
    ? 'complete'
    : 'incomplete';

return [
  {
    json: {
      booking_event_id: bookingEventId,
      gmail_thread_id: gmailThreadId,

      meeting_title: eventType,
      meeting_start: meetingStart,
      meeting_parse_status: meetingParseStatus,
      meeting_parse_error: meetingParseError,

      prospect_name: prospectName,
      first_name: firstName,
      last_name: lastName,
      email,

      email_domain: emailDomain,
      is_free_email: isFreeEmail,
      company_domain: companyDomain,
      company_name: companyName,

      booking_notes: '',
      booking_source: 'Calendly notification email',

      email_subject: subject,

      extraction_status: extractionStatus,
      missing_fields: missingFields,

      processed_at: new Date().toISOString()
    }
  }
];

const lead = $json;

let score = 0;
const reasons = [];

/*
  Company size:
  example-company may be especially relevant to growing technology
  companies that need compliance for enterprise sales.
*/
const employeeCount = Number(lead.employee_count || 0);

if (employeeCount >= 20 && employeeCount <= 200) {
  score += 25;
  reasons.push('Company has 20–200 employees: +25');
} else if (employeeCount >= 10 && employeeCount < 20) {
  score += 10;
  reasons.push('Company has 10–19 employees: +10');
} else if (employeeCount > 200 && employeeCount <= 500) {
  score += 15;
  reasons.push('Company has 201–500 employees: +15');
}

/*
  Industry fit
*/
const industry = String(lead.industry || '').toLowerCase();

if (
  industry.includes('software') ||
  industry.includes('saas') ||
  industry.includes('artificial intelligence') ||
  industry.includes('cybersecurity') ||
  industry.includes('technology')
) {
  score += 25;
  reasons.push('Technology-sector fit: +25');
}

/*
  Enterprise selling motion
*/
if (lead.sells_to_enterprise === true) {
  score += 25;
  reasons.push('Sells to enterprise customers: +25');
}

/*
  Geography
*/
const europeanCountries = new Set([
  'France',
  'Germany',
  'Netherlands',
  'Belgium',
  'Spain',
  'Italy',
  'Portugal',
  'Ireland',
  'United Kingdom',
  'Sweden',
  'Denmark',
  'Norway',
  'Finland',
  'Switzerland',
  'Austria',
  'Poland'
]);

if (europeanCountries.has(lead.country)) {
  score += 10;
  reasons.push('European company: +10');
}

/*
  Growth/funding signal
*/
const fundingStage = String(
  lead.funding_stage || ''
).toLowerCase();

if (
  fundingStage.includes('seed') ||
  fundingStage.includes('series a') ||
  fundingStage.includes('series b') ||
  fundingStage.includes('series c')
) {
  score += 15;
  reasons.push('Growth-stage funding signal: +15');
}

score = Math.min(score, 100);

let tier = 'Low';

if (score >= 70) {
  tier = 'High';
} else if (score >= 40) {
  tier = 'Medium';
}

return [
  {
    json: {
      ...lead,
      icp_score: score,
      icp_tier: tier,
      icp_reasons: reasons.join('\n')
    }
  }
];

