parameters.jsCode:
const raw = $json.output ?? $json;

const enriched = typeof raw === 'string'
  ? JSON.parse(raw)
  : raw;

const booking = $('Parse Calendly Booking').item.json;
const contactRaw = $('Upsert HubSpot Contact').item.json;

const contactId =
  contactRaw.id ||
  contactRaw.results?.[0]?.id ||
  contactRaw.body?.id ||
  contactRaw.body?.results?.[0]?.id ||
  null;

return [
  {
    json: {
      ...booking,

      contact_id: contactId,
      company_domain: booking.company_domain,

      enrichment_status: enriched.enrichment_status || 'not_found',
      enrichment_source: 'ai_web_research',
      enrichment_error: enriched.enrichment_status === 'error' ? 'AI enrichment failed' : '',
      enriched_at: new Date().toISOString(),

      enriched_company_name: enriched.enriched_company_name || booking.company_name || null,
      website: enriched.website || null,
      industry: enriched.industry || null,
      employee_count: enriched.employee_count ?? null,
      employee_range: enriched.employee_range || null,
      country: enriched.country || null,
      city: enriched.city || null,
      business_model: enriched.business_model || null,
      sells_to_enterprise: enriched.sells_to_enterprise ?? null,
      funding_stage: enriched.funding_stage || null,
      company_linkedin_url: enriched.company_linkedin_url || null,
      technologies: Array.isArray(enriched.technologies) ? enriched.technologies : [],
      source_urls: Array.isArray(enriched.source_urls) ? enriched.source_urls : [],
      confidence: enriched.confidence || 'low'
    }
  }
];

const cache = $json;
const booking = $('Process One Company At A Time').item.json;

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  if (!value || value === '') return [];

  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    return [];
  }
}

return [
  {
    json: {
      ...booking,

      contact_id: booking.contact_id ?? $('Upsert HubSpot Contact').item.json.id,
      company_domain: booking.company_domain,

      enrichment_status: cache.enrichment_status,
      enrichment_source: 'cache',
      enrichment_error: cache.enrichment_error || '',
      enriched_at: cache.last_enriched_at,

      enriched_company_name: cache.enriched_company_name || null,
      website: cache.website || null,
      industry: cache.industry || null,
      employee_count: cache.employee_count ? Number(cache.employee_count) : null,
      employee_range: cache.employee_range || null,
      country: cache.country || null,
      city: cache.city || null,
      business_model: cache.business_model || null,
      sells_to_enterprise:
        cache.sells_to_enterprise === true ||
        cache.sells_to_enterprise === 'true',
      funding_stage: cache.funding_stage || null,
      company_linkedin_url: cache.company_linkedin_url || null,
      technologies: parseJsonArray(cache.technologies),
      source_urls: parseJsonArray(cache.source_urls),
      confidence: cache.confidence || 'low'
    }
  }
];

